1	// /plan2 — the postcard trip planner, page logic.
2	//
3	// A wizard whose every answer becomes a sticker on a postcard, then the
4	// postcard turned over: a calendar of vertical days with one ticket per plan
5	// item, each of which peels off to reveal what to correct. The drafting itself
6	// is ./lib/draft.js (pure, deterministic); this file is state, rendering and
7	// gestures only. State persists in localStorage so the trip survives a reload.
8	
9	import { cityOf, festivalsIn, festivalsOn, routesFrom, showsOf, perfsBetween, daysBetween, addDays, dayOfWeek, monthName, shortDate, toMin, fromMin, citiesInMonth, genresOf, venueOf } from "./lib/world.js";
10	import { draftTrip, gapsOf, pickStay, pickRoute, DAY_START } from "./lib/draft.js";
11	
12	const STORE_KEY = "edfringe.plan2.v1";
13	const STEPS = ["where", "when", "who", "matters", "travel", "sleep", "draft"];
14	const CARD_TITLES = { where: "Where to?", when: "When?", who: "Who's coming?", matters: "What matters?", travel: "Getting there?", sleep: "Where to sleep?" };
15	const HOUR_PX = 40;
16	
17	const MODE_PIC = { train: "il-train", plane: "il-plane", car: "il-car", coach: "il-coach" };
18	const MODE_WORD = { train: "Train", plane: "Fly", car: "Drive", coach: "Coach" };
19	const COST = [["thrifty", "Thrifty", "il-wallet"], ["between", "In between", "il-jar"], ["splash", "Splash out", "il-champagne"]];
20	const PACE = [["packed", "Packed", "il-sprint"], ["steady", "Steady", "il-stroll"], ["leisurely", "Leisurely", "il-deckchair"]];
21	const FOCUS = [["festival", "Festival only", "il-curtain"], ["mix", "A mix", "il-picnic"], ["city", "City too", "il-city"]];
22	const PARTY = [["solo", "Just me", "il-solo"], ["couple", "A couple", "il-couple"], ["family", "Family", "il-family"], ["group", "Friends", "il-group"]];
23	const SLEEP = [["cost", "Cost", "il-wallet"], ["comfort", "Comfort", "il-hotel"], ["location", "Location", "ic-pin"]];
24	const AGES = [3, 5, 7, 9, 12, 15];
25	
26	const stage = document.getElementById("stage");
27	let world = null;
28	let state = null;
