33	function fresh() {
34	  return { v: 1, step: "where", answers: { cityId: null, festivalIds: [], from: null, to: null, party: null, cost: null, pace: null, focus: null, originId: null, mode: null, sleep: [] }, rules: {}, starred: [] };
