37	function load() {
38	  try {
39	    const raw = localStorage.getItem(STORE_KEY);
40	    if (raw) {
41	      const s = JSON.parse(raw);
42	      if (s && s.v === 1) return { ...fresh(), ...s, answers: { ...fresh().answers, ...s.answers } };
43	    }
44	  } catch (_) { /* a blocked or corrupt store just means a fresh postcard */ }
45	  return fresh();
46	}
