60	const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
61	const use = (id, cls = "") => `<svg class="${cls}"><use href="#${id}"></use></svg>`;
62	const money = (city, n) => `${city.currency}${Number.isInteger(n) ? n : n.toFixed(2)}`;
63	const RING = `<svg class="ring" viewBox="0 0 140 110" preserveAspectRatio="none"><path d="M18 60C6 22 60 6 100 12c30 5 40 30 30 60-10 32-70 40-104 20C10 84 10 66 30 52"></path></svg>`;
