65	function answered(step) {
66	  const a = state.answers;
67	  switch (step) {
68	    case "where": return Boolean(a.cityId && a.festivalIds.length);
69	    case "when": return Boolean(a.from && a.to);
70	    case "who": return Boolean(a.party && (a.party.type !== "family" || (a.party.ages && a.party.ages.length)));
71	    case "matters": return Boolean(a.cost && a.pace && a.focus);
72	    case "travel": return Boolean(a.originId && a.mode);
73	    case "sleep": return a.sleep.length === 2;
74	    default: return true;
75	  }
