78	// The first question still without an answer, or null when the trip is
79	// fully described. The draft is only ever rendered in the null case: a
80	// question reopened and left half-answered comes back before the calendar.
81	function firstUnanswered() {
82	  return STEPS.find((step) => step !== "draft" && !answered(step)) || null;
83	}
