94	function dateRange() {
95	  const a = state.answers;
96	  if (!a.from) return "";
97	  const [, m1, d1] = a.from.split("-").map(Number);
98	  const [, , d2] = a.to.split("-").map(Number);
99	  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
100	  return `${d1}–${d2} ${months[m1 - 1]}`;
