139	  if (exceptStep !== "where" && city && answered("where")) {
140	    st("where", "label", -3, `${use("ic-pin")}${esc(city.name)}`);
141	  }
142	  if (exceptStep !== "when" && answered("when")) st("when", "label sun", 2, `${use("ic-sun")}${esc(dateRange())}`);
143	  if (exceptStep !== "who" && answered("who")) {
144	    const p = PARTY.find((x) => x[0] === a.party.type);
145	    const ages = a.party.type === "family" ? `<span class="sub">${a.party.ages.join(" · ")}</span>` : "";
146	    st("who", "wide", -2, `${use(p[2])}${p[1]}${ages}`);
147	  }
148	  if (exceptStep !== "matters" && answered("matters")) {
149	    st("matters", "sun", 4, `${use(COST.find((x) => x[0] === a.cost)[2])}${COST.find((x) => x[0] === a.cost)[1]}`);
150	    st("matters", "rose", -3, `${use(PACE.find((x) => x[0] === a.pace)[2])}${PACE.find((x) => x[0] === a.pace)[1]}`);
151	    st("matters", "mint", 2, `${use(FOCUS.find((x) => x[0] === a.focus)[2])}${FOCUS.find((x) => x[0] === a.focus)[1]}`);
