249	        <div class="cal"><span class="h">M</span><span class="h">T</span><span class="h">W</span><span class="h">T</span><span class="h">F</span><span class="h">S</span><span class="h">S</span>${cells.join("")}</div>
250	        <div class="foot"><span class="note" style="color:var(--ink-faint);font-size:20px">${f ? esc(f.short) + " runs " + esc(f.from.slice(8)) + "–" + esc(f.to.slice(8)) : ""}</span><span class="note">${nights() ? nights() + " nights" : a.from ? "…and back?" : ""}</span></div>`;
