307	  } else if (it.kind === "meal") inner = S("", "il-table", "Somewhere else", "notMeal", -3) + S("rose", "ic-nope", "No meals", "noMeals", 2) + S("keep", "ic-star", "Keep it", "keep", 3);
308	  else if (it.kind === "out") inner = S("", "il-picnic", "Not this one", "notOut", -3) + S("rose", "ic-nope", "No day out", "noDayOut", 2) + S("keep", "ic-star", "Keep it", "keep", 3);
309	  else if (it.kind === "travel") inner = S("", "ic-clock", "Earlier", "earlier", -3) + S("", "ic-clock", "Later", "later", 2) + S("keep", "ic-star", "Keep it", "keep", 3);
310	  else if (it.kind === "stay") inner = S("", "il-hotel", "Another stay", "otherStay", -3) + S("keep", "ic-star", "Keep it", "keep", 3);
311	  return `<div class="reveal" style="top:${top}px;${side}">${inner}</div>`;
312	}
313	
314	function renderBack() {
315	  const a = state.answers;
316	  const city = cityOf(world, a.cityId);
317	  const trip = draftTrip(world, a, state.rules, state.starred);
318	  const days = trip.days;
319	  const hours = [];
320	  for (let h = 8; h <= 24; h++) hours.push(`<span style="top:${(h - 8) * HOUR_PX}px">${String(h).padStart(2, "0")}:00</span>`);
321	  const cols = days.map((d, di) => {
322	    const items = [...d.items];
323	    for (const g of gapsOf(d)) items.push({ kind: "free", start: g.start, end: Math.min(g.end, 24 * 60) });
324	    items.sort((x, y) => x.start - y.start);
325	    let peelHtml = "";
326	    const tickets = items.map((it) => {
327	      const key = `${di}:${it.kind}:${it.id || it.title}:${it.start}`;
328	      if (ui.peel === key) {
329	        const h = Math.max(26, ((it.end - it.start) / 60) * HOUR_PX - 4);
330	        const side = di >= days.length - 2 ? "right:-6px" : "left:-6px";
331	        peelHtml = revealHtml(it, city, ((it.start - DAY_START) / 60) * HOUR_PX + h + 8, side);
332	      }
333	      return ticketHtml(it, city, key);
334	    });
335	    return `<div class="daycol" data-day="${d.date}">${tickets.join("")}${peelHtml}</div>`;
336	  });
337	  const fest = primaryFestival();
338	  const stay = trip.stay;
339	  return `
340	  <div class="draft-head"><span class="title-hand">First draft</span><span class="pen-note">peel off what's wrong</span></div>
341	  <div class="draft-answers">${answerStickers("none")}</div>
342	  <div class="postcard back" style="--days:${days.length}">
343	    <div class="head">POST CARD</div>
344	    <div class="divider"></div>
345	    <div class="calwrap">
346	      <div class="calgrid">
347	        <div></div>${days.map((d) => `<div class="dayhead">${esc(shortDate(d.date).slice(0, 3))} ${Number(d.date.slice(8))}<small>${(n => n === 1 ? "1 show" : `${n} shows`)(d.items.filter((i) => i.kind === "show").length)}</small></div>`).join("")}
348	        <div class="hours">${hours.join("")}</div>${cols.join("")}
349	      </div>
350	    </div>
351	    <div class="stampbox"></div>
352	    ${fest ? stampHtml(fest, "", "right: 38px; top: 52px; --r: -2deg;") : ""}
353	    ${postmarkHtml(city, "right: 110px; top: 30px; transform: rotate(-6deg); width: 240px; height: 104px;")}
354	    <div class="addr"><span>${esc(stay.name)}</span><span>${esc(stay.address.split(",")[0])}</span><span>${esc(city.name)} ${esc(stay.address.split(",")[1] || "")}</span></div>
355	    <div class="totals"><span>${trip.totals.nights} nights <b>${money(city, trip.totals.stayCost)}</b></span><span>${MODE_WORD[trip.route ? trip.route.mode : "train"]} <b>${money(city, trip.totals.travel)}</b></span><span>Tickets <b>${money(city, trip.totals.tickets)}</b></span></div>
356	    <div class="nothing">Nothing booked yet</div>
357	    <div class="sheet"><div class="title">Stick on…</div>
358	      <button type="button" class="sticker mint" style="--r:-4deg" data-stick="out">${use("il-picnic")}Day out</button>
359	      <button type="button" class="sticker sun" style="--r:3deg" data-stick="meal">${use("il-table")}A meal</button>
360	      <button type="button" class="sticker lilac" style="--r:-2deg" data-stick="pick">${use("il-booklet")}Pick myself</button>
361	    </div>
362	  </div>
363	  <div class="draft-foot"><button type="button" class="tag-cta violet" style="--r:-2deg" data-nav="done">Looks good ${use("ic-tick")}</button></div>
364	  ${ui.chooser ? renderChooser(city, trip) : ""}`;
365	}
366	
367	function renderChooser(city, trip) {
368	  const a = state.answers;
369	  const inPlan = new Set(trip.days.flatMap((d) => d.items).filter((i) => i.kind === "show").map((i) => i.id));
370	  const days = daysBetween(a.from, a.to);
371	  const groups = a.festivalIds.map((fid) => {
372	    const f = world.festivals.find((x) => x.id === fid);
373	    const shows = showsOf(world, [fid]).filter((s) => perfsBetween(s, a.from, a.to).length);
374	    const starred = shows.filter((s) => state.starred.includes(s.id));
375	    const rest = shows.filter((s) => !state.starred.includes(s.id)).sort((x, y) => x.title.localeCompare(y.title));
376	    const limit = 5 + ui.more * 20;
377	    const rows = [...starred, ...rest.slice(0, limit)];
378	    const row = (s) => {
379	      const perfs = perfsBetween(s, a.from, a.to);
380	      const nightsOn = days.map((d) => perfs.some((p) => p.date === d));
381	      const venue = venueOf(city, s.venueId);
382	      return `<div class="crow ${state.starred.includes(s.id) ? "is-on" : ""}">
383	        <button type="button" class="starbtn" data-star="${s.id}" aria-label="Star ${esc(s.title)}">${use("ic-star")}</button>
384	        <div><div class="ttl">${esc(s.title)} ${inPlan.has(s.id) ? `<small class="meta">· in the plan</small>` : ""}</div><div class="meta">${esc(s.genre)} · ${esc(venue ? venue.name : "")} · ${s.minutes} min${s.ages ? ` · ${s.ages}+` : ""}${perfs.length === 1 ? " · one night only" : ""}</div></div>
385	        <div class="nights">${nightsOn.map((on) => `<i class="${on ? "on" : ""}"></i>`).join("")}</div>
386	        <div class="price">${s.price ? money(city, s.price) : "Free"}</div></div>`;
387	    };
388	    return `<h3><i style="--band:${f.colour}"></i>${esc(f.name)} <small>${shows.length} on your dates · ${starred.length} starred</small></h3>${rows.map(row).join("")}
389	      ${rest.length > limit ? `<div class="more"><button type="button" class="chip" data-more>Show 20 more of ${rest.length - limit}</button></div>` : ""}`;
390	  });
391	  return `<div class="chooser" id="chooser"><div class="book">
392	    <button type="button" class="tag-cta quiet close" style="--r:2deg" data-close-chooser>Back to the postcard ${use("ic-back")}</button>
393	    <h2>Pick myself</h2><p class="lede">Star what you want in. Starred shows stay in the plan and are never swapped.</p>
394	    ${groups.join("")}</div></div>`;
395	}
396	
397	// --------------------------------------------------------------- wiring --
398	
399	function next() {
400	  const i = STEPS.indexOf(state.step);
401	  set((s) => { s.step = STEPS[Math.min(STEPS.length - 1, i + 1)]; });
402	}
403	
404	function wire() {
405	  const on = (sel, fn) => stage.querySelectorAll(sel).forEach((el) => el.addEventListener("click", (e) => fn(el, e)));
406	  on("[data-nav]", (el) => {
407	    const nav = el.dataset.nav;
408	    if (nav === "next") next();
409	    else if (nav === "back") set((s) => { s.step = STEPS[Math.max(0, STEPS.indexOf(s.step) - 1)]; });
410	    else if (nav === "done") el.textContent = "Saved to this browser ✓";
411	  });
412	  on("[data-reopen]", (el) => { ui.peel = null; set((s) => { s.step = el.dataset.reopen; }); });
413	  on("[data-way]", (el) => { ui.way = el.dataset.way; render(); });
414	  on("[data-city]", (el) => pickCity(el.dataset.city));
415	  on("[data-month]", (el) => { ui.month = Number(el.dataset.month); render(); });
416	  on("[data-genre]", (el) => { ui.genre = el.dataset.genre; render(); });
417	  on("[data-pick-fest]", (el) => { const f = world.festivals.find((x) => x.id === el.dataset.pickFest); pickCity(f.cityId, f.id); });
418	  const nb = stage.querySelector("#nameBox");
419	  if (nb) { nb.addEventListener("input", () => { ui.nameQuery = nb.value; const pos = nb.selectionStart; render(); const again = stage.querySelector("#nameBox"); if (again) { again.focus(); again.setSelectionRange(pos, pos); } }); }
420	  on("[data-fest]", (el) => set((s) => { const id = el.dataset.fest; if (!s.answers.festivalIds.includes(id)) s.answers.festivalIds.push(id); }));
421	  on("[data-month-nav]", (el) => { ui.month = el.dataset.monthNav; render(); });
422	  on("[data-day]", (el) => set((s) => {
423	    const d = el.dataset.day;
424	    const a = s.answers;
425	    if (!a.from || (a.from && a.to)) { a.from = d; a.to = null; }
426	    else if (d < a.from) { a.to = a.from; a.from = d; }
427	    else if (d === a.from) { a.from = null; }
428	    else a.to = d;
429	    if (a.from && a.to) a.festivalIds = a.festivalIds.filter((id) => { const f = world.festivals.find((x) => x.id === id); return f.from <= a.to && f.to >= a.from; });
430	  }));
431	  on("[data-party]", (el) => set((s) => { const type = el.dataset.party; s.answers.party = { type, ages: type === "family" ? (s.answers.party && s.answers.party.ages) || [] : [] }; }));
432	  on("[data-age]", (el) => set((s) => { const n = Number(el.dataset.age); const ages = s.answers.party.ages; const i = ages.indexOf(n); if (i >= 0) ages.splice(i, 1); else ages.push(n); ages.sort((x, y) => x - y); }));
433	  on("[data-cost]", (el) => set((s) => { s.answers.cost = el.dataset.cost; }));
434	  on("[data-pace]", (el) => set((s) => { s.answers.pace = el.dataset.pace; }));
435	  on("[data-focus]", (el) => set((s) => { s.answers.focus = el.dataset.focus; }));
436	  on("[data-origin]", (el) => set((s) => { s.answers.originId = el.dataset.origin; const modes = routesFrom(world, s.answers.originId, s.answers.cityId); if (!modes.some((r) => r.mode === s.answers.mode)) s.answers.mode = null; }));
437	  on("[data-mode]", (el) => set((s) => { s.answers.mode = el.dataset.mode; }));
438	  on("[data-sleep]", (el) => set((s) => { const k = el.dataset.sleep; const sl = s.answers.sleep; const i = sl.indexOf(k); if (i >= 0) sl.splice(i, 1); else { sl.push(k); if (sl.length > 2) sl.shift(); } }));
439	  // the back
440	  on("[data-peel]", (el, e) => { e.stopPropagation(); ui.peel = ui.peel === el.dataset.peel ? null : el.dataset.peel; render(); });
441	  on("[data-act]", (el, e) => { e.stopPropagation(); correct(el.dataset.act); });
442	  on("[data-stick]", (el) => stick(el.dataset.stick));
443	  on("[data-close-chooser]", () => { ui.chooser = false; render(); });
444	  on("[data-more]", () => { ui.more += 1; render(); });
445	  on("[data-star]", (el) => set((s) => { const id = el.dataset.star; const i = s.starred.indexOf(id); if (i >= 0) s.starred.splice(i, 1); else s.starred.push(id); }));
446	  const chooser = stage.querySelector("#chooser");
447	  if (chooser) chooser.addEventListener("click", (e) => { if (e.target === chooser) { ui.chooser = false; render(); } });
448	}
449	
450	function pickCity(cityId, festivalId) {
451	  set((s) => {
452	    const a = s.answers;
453	    if (a.cityId !== cityId) { a.from = null; a.to = null; a.originId = null; a.mode = null; s.rules = {}; s.starred = []; }
454	    a.cityId = cityId;
455	    const fests = festivalsIn(world, cityId);
456	    a.festivalIds = festivalId ? [festivalId] : [fests[0].id];
457	    ui.month = null;
458	  });
459	}
460	
461	// A correction is a rule the drafter obeys from now on; the peeled ticket's
462	// own facts (which show, which genre, which venue, which night) are the rule.
463	function correct(act) {
464	  const key = ui.peel;
465	  if (!key) return;
466	  const [di, kind] = key.split(":");
467	  const a = state.answers;
468	  const trip = draftTrip(world, a, state.rules, state.starred);
469	  const day = trip.days[Number(di)];
470	  const it = day && day.items.find((x) => `${di}:${x.kind}:${x.id || x.title}:${x.start}` === key);
471	  if (!it && kind !== "free") { ui.peel = null; render(); return; }
472	  const push = (r, k, v) => { r[k] = r[k] || []; if (!r[k].includes(v)) r[k].push(v); };
473	  set((s) => {
474	    const r = s.rules;
475	    switch (act) {
476	      case "keep": if (it.kind === "show" && !s.starred.includes(it.id)) s.starred.push(it.id); break;
477	      case "notTime": push(r, "notTime", it.perf); break;
478	      case "notShow": push(r, "notShow", it.id); s.starred = s.starred.filter((x) => x !== it.id); break;
479	      case "notGenre": push(r, "notGenre", it.genre); break;
480	      case "notVenue": push(r, "notVenue", it.venueId); break;
481	      case "notMeal": push(r, "notMeal", it.id); break;
482	      case "noMeals": r.noMeals = true; break;
483	      case "notOut": push(r, "notOut", it.id); break;
484	      case "noDayOut": r.noDayOut = true; r.stickOut = []; break;
485	      case "earlier": r.travelShift = (r.travelShift || 0) - 1; break;
486	      case "later": r.travelShift = (r.travelShift || 0) + 1; break;
487	      case "otherStay": {
488	        const city = cityOf(world, a.cityId);
489	        const cur = pickStay(city, a);
490	        push(r, "notStay", cur.id);
491	        break;
492	      }
493	      default: break;
494	    }
495	  });
496	  ui.peel = null;
497	  render();
498	}
499	
500	function stick(what) {
501	  if (what === "pick") { ui.chooser = true; ui.more = 0; render(); return; }
502	  const a = state.answers;
503	  const days = daysBetween(a.from, a.to);
504	  set((s) => {
505	    const r = s.rules;
506	    if (what === "out") {
507	      r.noDayOut = false;
508	      const trip = draftTrip(world, a, r, s.starred);
509	      const free = trip.days.slice(1, -1).find((d) => !d.items.some((i) => i.kind === "out"));
510	      if (free) { r.stickOut = r.stickOut || []; r.stickOut.push(free.date); }
511	    } else if (what === "meal") {
512	      r.noMeals = false;
513	      r.notMeal = [];
514	      const trip = draftTrip(world, a, r, s.starred);
515	      const lacking = trip.days.find((d) => !d.items.some((i) => i.kind === "meal" && i.start >= 17 * 60));
516	      if (lacking) { r.stickMeal = r.stickMeal || []; if (!r.stickMeal.includes(lacking.date)) r.stickMeal.push(lacking.date); }
517	    }
518	  });
519	  void days;
520	}
521	
522	// ----------------------------------------------------------------- boot --
523	
524	async function boot() {
525	  if (new URLSearchParams(location.search).has("reset")) { try { localStorage.removeItem(STORE_KEY); } catch (_) { /* fine */ } history.replaceState(null, "", location.pathname); }
526	  const [symbols, data] = await Promise.all([fetch("symbols.svg").then((r) => r.text()), fetch("data/world.json").then((r) => r.json())]);
527	  document.getElementById("symbols").innerHTML = symbols;
528	  world = data;
529	  state = load();
530	  document.getElementById("resetBtn").addEventListener("click", () => { state = fresh(); ui = { way: "city", month: null, peel: null, chooser: false, more: 0, nameQuery: "" }; save(); render(); });
531	  render();
532	  document.body.dataset.ready = "1";
533	}
534	
535	boot();
536

