1	/* /plan2 — the postcard trip planner. Visual system from the Postcard design
2	   direction (design-concepts/trip-planner/v2/postcard): kraft desk, a postcard
3	   that fills itself in, index-card questions, stickers for answers, ticket
4	   stubs on a calendar, and a peel that reveals the corrections. */
5	:root {
6	  --ink: #2b2118; --ink-soft: #6b5a48; --ink-faint: #a08b70;
7	  --desk: #d3b990; --desk-2: #c4a77b;
8	  --paper: #fbf4e6; --paper-2: #f2e6cf; --card: #fffdf8;
9	  --rule: #b8c8d8; --rule-red: #e0857a;
10	  --red: #d0432f; --teal: #2a8a84; --gold: #e8b64a; --violet: #6c4cf1; --sky: #a9d6ea;
11	  --green: #86b862; --pink: #f0a1b8; --brown: #8b5e3c; --navy: #2e4a7a; --skin: #f2c8a2;
12	  --hand: "Caveat", "Segoe Print", "Bradley Hand", cursive;
13	  --body: "Nunito", "Segoe UI", "Liberation Sans", system-ui, sans-serif;
14	  --hour: 40px;
15	}
16	* { box-sizing: border-box; }
17	html, body { margin: 0; padding: 0; }
18	body { background: var(--desk); font-family: var(--body); color: var(--ink); font-size: 15px; line-height: 1.3; min-height: 100vh; }
19	svg { display: block; }
20	button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
21	button:focus-visible, [tabindex]:focus-visible { outline: 3px solid var(--violet); outline-offset: 3px; }
22	
23	.desk { position: relative; width: 1240px; margin: 0 auto; padding: 0 0 60px; min-height: 100vh; }
24	.desk::before { content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 0;
25	  background: radial-gradient(ellipse at 30% 20%, rgba(255,255,255,.25), transparent 60%), radial-gradient(ellipse at 80% 90%, rgba(80,50,20,.18), transparent 55%); }
26	.stage { position: relative; z-index: 1; }
27	
28	/* brand + nav */
29	.topbar { display: flex; align-items: center; justify-content: space-between; height: 72px; padding: 0 8px; }
30	.brand { display: flex; align-items: center; gap: 10px; font-family: var(--hand); font-size: 28px; color: var(--ink); text-decoration: none; }
31	.brand .dot { width: 14px; height: 14px; border-radius: 50%; background: var(--red); box-shadow: 0 0 0 3px var(--paper); }
32	.brand b { font-weight: 700; } .brand i { font-style: normal; color: var(--violet); }
33	.topnav { display: flex; gap: 18px; font-family: var(--hand); font-size: 22px; font-weight: 700; }
34	.topnav a { color: var(--ink-soft); text-decoration: none; padding-bottom: 2px; border-bottom: 2px solid transparent; min-height: 44px; display: inline-flex; align-items: center; }
35	.topnav a.is-active { color: var(--red); border-bottom-color: var(--red); }
36	.topnav button { color: var(--ink-faint); font-family: var(--body); font-size: 12px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; min-height: 44px; padding: 0 8px; }
37	
38	/* washi tape */
39	.tape { position: absolute; width: 130px; height: 30px; opacity: .88; z-index: 5; pointer-events: none;
40	  background: repeating-linear-gradient(45deg, rgba(255,255,255,.7) 0 7px, rgba(208,67,47,.55) 7px 14px); box-shadow: 0 1px 2px rgba(60,40,10,.25); }
41	.tape.teal { background: repeating-linear-gradient(-45deg, rgba(255,255,255,.7) 0 7px, rgba(42,138,132,.55) 7px 14px); }
42	.tape.gold { background: repeating-linear-gradient(45deg, rgba(255,255,255,.7) 0 7px, rgba(232,182,74,.7) 7px 14px); }
43	
44	/* ===================== the postcard, front ===================== */
45	.front { position: relative; height: 940px; }
46	.postcard { position: absolute; background: var(--paper); border-radius: 6px;
47	  background-image: radial-gradient(ellipse at 50% 40%, #fdf8ec 55%, #f0e3ca 100%);
48	  box-shadow: inset 0 0 0 1px rgba(255,255,255,.7), 0 30px 50px -28px rgba(60,40,10,.6), 0 4px 10px -4px rgba(60,40,10,.3); }
