263	.chooser h2 { font-family: var(--hand); font-size: 44px; margin: 0; }
264	.chooser .lede { font-family: var(--hand); font-size: 24px; color: var(--ink-soft); margin: 4px 0 14px; }
265	.chooser h3 { display: flex; align-items: center; gap: 10px; font-family: var(--hand); font-size: 30px; margin: 18px 0 8px; }
266	.chooser h3 i { width: 12px; height: 26px; border-radius: 4px; background: var(--band); }
267	.chooser h3 small { font-family: var(--body); font-size: 14px; font-weight: 700; color: var(--ink-faint); }
268	.crow { display: grid; grid-template-columns: 44px 1fr 150px 70px; align-items: center; gap: 12px; padding: 6px 8px; border-radius: 10px; }
269	.crow:hover { background: rgba(224,133,122,.08); }
270	.crow.is-on { background: #fff7dc; }
271	.crow .starbtn { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; color: #c9bfae; }
272	.crow.is-on .starbtn { color: var(--gold); }
273	.crow .starbtn svg { width: 28px; height: 28px; }
274	.crow .ttl { font-family: var(--hand); font-weight: 700; font-size: 22px; line-height: 1; }
275	.crow .meta { font-size: 12px; color: var(--ink-faint); }
276	.crow .nights { display: flex; gap: 3px; }
277	.crow .nights i { width: 26px; height: 18px; border-radius: 3px; background: #eef0f5; }
278	.crow .nights i.on { background: var(--teal); }
279	.crow .price { font-family: var(--hand); font-weight: 700; font-size: 22px; text-align: right; }
280	.more { display: flex; justify-content: center; margin-top: 8px; }
281	.more .chip { font-size: 20px; }
282	.chooser .close { position: sticky; top: 0; float: right; }
283	
284	/* the dev tray: the world's other trips, to play with */
285	.tray { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; padding: 20px 12px 0; font-family: var(--body); font-size: 12px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-faint); }
286	.tray .chip { font-size: 18px; min-height: 40px; }
287	[hidden] { display: none !important; }
