"use strict";
const { plan2Ready, settle } = require("../../shared/case-helpers");
const { plan2Storage } = require("../../shared/plan2-fixture");

// Two peels, side by side: a repeating show's five correction stickers, then
// a one-off's single "Not for me". Each is captured as the ticket plus the
// sheet it reveals; the golden is the two crops stitched.
async function peel(page, tools, selector) {
  await page.click(selector);
  await settle(page);
  return tools.unionClip([`${selector}.lift`, ".reveal"], 12);
}

module.exports = {
  description: "peeling a ticket reveals the correction stickers; a one-off reveals only Not for me",
  page: "/plan2/",
  viewport: "desktop",
  localStorage: plan2Storage("draft"),
  ready: plan2Ready,
  capture: async (page, tools) => {
    const repeating = await peel(page, tools, '.tix[data-kind="show"]:not([data-oneoff])');
    const oneOff = await peel(page, tools, '.tix[data-oneoff]');
    return tools.stitchH([repeating, oneOff], 24);
  },
};

// The one trip every /plan2 screen case renders: a family of four from
// London, four thrifty and packed August nights in Edinburgh, Fringe plus the
// International Festival, with the one-night Chineke! concert starred so the
// draft carries both a repeating show and a one-off. Cases seed it into
// storage at the step they show.
"use strict";

const STORE_KEY = "edfringe.plan2.v1";

const ANSWERS = {
  cityId: "edinburgh",
  festivalIds: ["fringe", "eif"],
  from: "2026-08-13",
  to: "2026-08-17",
  party: { type: "family", ages: [5, 9] },
  cost: "thrifty",
  pace: "packed",
  focus: "mix",
  originId: "london",
  mode: "train",
  sleep: ["cost", "location"],
};

const STARRED = ["chineke"];

function plan2Storage(step, overrides = {}) {
  return { [STORE_KEY]: JSON.stringify({ v: 1, step, answers: { ...ANSWERS, ...(overrides.answers || {}) }, rules: overrides.rules || {}, starred: overrides.starred || STARRED }) };
}

module.exports = { plan2Storage, ANSWERS, STARRED, STORE_KEY };

